function(container, apiUrl, tables) {
  const oldVersionSelect = container.querySelector('[data-testid="old-version-select"]');
  const newVersionSelect = container.querySelector('[data-testid="new-version-select"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const exportBtn = container.querySelector('[data-testid="export-button"]');
  const detailBtn = container.querySelector('[data-testid="detail-button"]');
  const backBtn = container.querySelector('[data-testid="back-button"]');

  // グラフ描画関数
  function drawSuccessRateChart() {
    const canvas = container.querySelector('#success-rate-chart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;
    ctx.fillStyle = '#fef3e2';
    ctx.fillRect(0, 0, w, h);

    const oldRate = 71.7;
    const newRate = 84.2;
    const barWidth = 60;
    const barHeight = (h - 40) * 0.8;
    const x1 = 40;
    const x2 = 140;
    const y0 = h - 30;

    // 軸
    ctx.strokeStyle = '#8b6f47';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(30, y0);
    ctx.lineTo(w - 10, y0);
    ctx.stroke();

    // 旧バージョンバー
    ctx.fillStyle = '#b45309';
    ctx.fillRect(x1 - barWidth / 2, y0 - (barHeight * oldRate / 100), barWidth, barHeight * oldRate / 100);
    ctx.fillStyle = '#2d1810';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('旧版', x1, y0 + 15);
    ctx.fillText(oldRate.toFixed(1) + '%', x1, y0 - (barHeight * oldRate / 100) - 5);

    // 新バージョンバー
    ctx.fillStyle = '#d97706';
    ctx.fillRect(x2 - barWidth / 2, y0 - (barHeight * newRate / 100), barWidth, barHeight * newRate / 100);
    ctx.fillStyle = '#2d1810';
    ctx.fillText('新版', x2, y0 + 15);
    ctx.fillText(newRate.toFixed(1) + '%', x2, y0 - (barHeight * newRate / 100) - 5);
  }

  function drawWeeklyTrendChart() {
    const canvas = container.querySelector('#weekly-trend-chart');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;
    ctx.fillStyle = '#fef3e2';
    ctx.fillRect(0, 0, w, h);

    const weeks = ['W1', 'W2', 'W3', 'W4'];
    const oldData = [28.3, 27.1, 26.5, 25.8];
    const newData = [15.8, 14.2, 13.5, 12.1];
    const padding = 30;
    const graphW = w - 2 * padding;
    const graphH = h - 2 * padding;
    const pointSpacing = graphW / (weeks.length - 1);

    // 軸
    ctx.strokeStyle = '#8b6f47';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, h - padding);
    ctx.lineTo(w - padding, h - padding);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, h - padding);
    ctx.stroke();

    // 旧バージョンライン
    ctx.strokeStyle = '#b45309';
    ctx.lineWidth = 2;
    ctx.beginPath();
    oldData.forEach((val, i) => {
      const x = padding + i * pointSpacing;
      const y = h - padding - (graphH * val / 30);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 新バージョンライン
    ctx.strokeStyle = '#d97706';
    ctx.lineWidth = 2;
    ctx.beginPath();
    newData.forEach((val, i) => {
      const x = padding + i * pointSpacing;
      const y = h - padding - (graphH * val / 30);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#2d1810';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'center';
    weeks.forEach((w, i) => {
      const x = padding + i * pointSpacing;
      ctx.fillText(w, x, h - padding + 15);
    });
  }

  // 検索ボタン
  searchBtn.addEventListener('click', async () => {
    const oldVer = oldVersionSelect.value;
    const newVer = newVersionSelect.value;
    if (!oldVer || !newVer) {
      alert('旧バージョンと新バージョンを選択してください');
      return;
    }
    drawSuccessRateChart();
    drawWeeklyTrendChart();
  });

  // CSVエクスポート
  exportBtn.addEventListener('click', async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;
    const headers = ['比較名', '旧バージョン', '新バージョン', '旧却下率', '新却下率', '改善率', '統計有意性'];
    const csv = ['\uFEFF' + headers.join(',')];
    rows.forEach(row => {
      csv.push([
        row.比較名 || '',
        row.旧アルゴリズムバージョンid || '',
        row.新アルゴリズムバージョンid || '',
        row.旧バージョン却下率 || '',
        row.新バージョン却下率 || '',
        row.改善率 || '',
        row.統計的有意性 ? 'はい' : 'いいえ'
      ].map(v => `"${v}"`).join(','));
    });
    const blob = new Blob([csv.join('\n')], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'algorithm_comparison_' + new Date().toISOString().split('T')[0] + '.csv';
    link.click();
  });

  // 詳細レポートボタン
  detailBtn.addEventListener('click', () => {
    window.showScreen('scr-1783764482661');
  });

  // ダッシュボードに戻る
  backBtn.addEventListener('click', () => {
    window.showScreen('scr-1783764291805');
  });

  // 初期描画
  setTimeout(() => {
    drawSuccessRateChart();
    drawWeeklyTrendChart();
  }, 100);
}

function(container, apiUrl, tables) {
  const form = container.querySelector('#proposal-form');
  const submitBtn = container.querySelector('[data-testid="submit-button"]');
  const cancelBtn = container.querySelector('[data-testid="cancel-button"]');
  const rejectionModalBtn = container.querySelector('[data-testid="view-rejection-categories"]');
  const weeklyModalBtn = container.querySelector('[data-testid="view-weekly-summary"]');
  const rejectionModal = container.querySelector('#rejection-categories-modal');
  const weeklyModal = container.querySelector('#weekly-summary-modal');
  const closeRejectionBtn = container.querySelector('[data-testid="close-rejection-modal"]');
  const closeWeeklyBtn = container.querySelector('[data-testid="close-weekly-modal"]');

  // 提案者名と日時を自動入力
  const proposerNameInput = form.querySelector('[name="proposer_name"]');
  const proposerDatetimeInput = form.querySelector('[name="proposal_datetime"]');

  // ローカルストレージからユーザー情報を取得（デモ用）
  const currentUser = JSON.parse(localStorage.getItem('currentUser') || '{"name":"山田太郎"}');
  proposerNameInput.value = currentUser.name || '山田太郎';
  proposerDatetimeInput.value = new Date().toLocaleString('ja-JP');

  // モーダル開閉
  rejectionModalBtn.addEventListener('click', () => {
    rejectionModal.style.display = 'flex';
  });
  weeklyModalBtn.addEventListener('click', () => {
    weeklyModal.style.display = 'flex';
  });
  closeRejectionBtn.addEventListener('click', () => {
    rejectionModal.style.display = 'none';
  });
  closeWeeklyBtn.addEventListener('click', () => {
    weeklyModal.style.display = 'none';
  });

  // モーダル背景クリックで閉じる
  rejectionModal.addEventListener('click', (e) => {
    if (e.target === rejectionModal) rejectionModal.style.display = 'none';
  });
  weeklyModal.addEventListener('click', (e) => {
    if (e.target === weeklyModal) weeklyModal.style.display = 'none';
  });

  // Esc キーでモーダルを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      rejectionModal.style.display = 'none';
      weeklyModal.style.display = 'none';
    }
  });

  // 提案登録
  submitBtn.addEventListener('click', async () => {
    const formData = new FormData(form);
    const metrics = Array.from(form.querySelectorAll('[name="metrics"]:checked')).map(el => el.value);

    const proposalData = {
      proposal_title: formData.get('proposal_title'),
      background: formData.get('background'),
      improvement_detail: formData.get('improvement_detail'),
      target_algorithm_version: formData.get('target_algorithm_version'),
      expected_effect: formData.get('expected_effect'),
      target_history_id: formData.get('target_history_id'),
      comparison_algorithm_version: formData.get('comparison_algorithm_version'),
      proposer_name: formData.get('proposer_name'),
      proposal_datetime: formData.get('proposal_datetime'),
      metrics: metrics.join(','),
      status: 'pending'
    };

    // バリデーション
    if (!proposalData.proposal_title || !proposalData.background || !proposalData.improvement_detail || 
        !proposalData.target_algorithm_version || !proposalData.expected_effect || !proposalData.target_history_id) {
      alert('必須項目をすべて入力してください');
      return;
    }

    // テーブルインデックスを特定（改善提案書テーブル）
    const tableIndex = tables.findIndex(t => t.tableName && t.tableName.includes('改善提案'));

    if (tableIndex >= 0) {
      const saved = await window.aivicApi.save(tableIndex, proposalData);
      if (saved) {
        alert('改善提案書を登録しました');
        form.reset();
        proposerNameInput.value = currentUser.name || '山田太郎';
        proposerDatetimeInput.value = new Date().toLocaleString('ja-JP');
        // ダッシュボードへ遷移
        window.showScreen('scr-1783764291805');
      }
    } else {
      alert('改善提案書テーブルが見つかりません');
    }
  });

  // キャンセル
  cancelBtn.addEventListener('click', () => {
    if (confirm('入力内容を破棄してもよろしいですか？')) {
      window.showScreen('scr-1783764291805');
    }
  });

  // 却下修正理由カテゴリを非同期で読み込み
  (async () => {
    const categoryTableIndex = tables.findIndex(t => t.tableName && t.tableName.includes('却下修正理由'));
    if (categoryTableIndex >= 0) {
      const categories = await window.aivicApi.list(categoryTableIndex);
      if (categories && categories.length > 0) {
        const tbody = container.querySelector('#rejection-categories-tbody');
        tbody.innerHTML = categories.map(cat => `
          <tr style="border-bottom: 1px solid var(--border);">
            <td style="padding: 8px; color: var(--text);">${cat.カテゴリ名 || cat.category_name || ''}</td>
            <td style="padding: 8px; color: var(--text-muted);">${cat.説明 || cat.description || ''}</td>
          </tr>
        `).join('');
      }
    }
  })();
}
